import{_ as e,o as p,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse(`{"title":"在移动端通过vue-pdf实现预览pdf","description":"应用场景： 比赛报表pdf文件需要在线预览跟下载，发现直接使用window.open(url, ' blank')，在pc端是可以实现预览，但是在移动端是直接通过打开浏览器进行下载再预览，经查资料发现可以使用vue pdf组件实现预览！！！ 参考： https://www.cnb。","frontmatter":{"title":"在移动端通过vue-pdf实现预览pdf","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"应用场景： 比赛报表pdf文件需要在线预览跟下载，发现直接使用window.open(url, ' blank')，在pc端是可以实现预览，但是在移动端是直接通过打开浏览器进行下载再预览，经查资料发现可以使用vue pdf组件实现预览！！！ 参考： https://www.cnb。","sidebarWeight":45,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/Vue-pdf/在移动端通过vue-pdf实现预览pdf.md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/Vue-pdf/在移动端通过vue-pdf实现预览pdf.md","filePath":"posts/Vue系统教程/07-项目实战/Vue-pdf/在移动端通过vue-pdf实现预览pdf.md"}`),r={name:"posts/Vue系统教程/07-项目实战/Vue-pdf/在移动端通过vue-pdf实现预览pdf.md"};function s(d,t,u,n,l,i){return p(),o("div",null,[...t[0]||(t[0]=[a('<div><h1 id="在移动端通过vue-pdf实现预览pdf" tabindex="-1">在移动端通过vue-pdf实现预览pdf <a class="header-anchor" href="#在移动端通过vue-pdf实现预览pdf" aria-label="Permalink to &quot;在移动端通过vue-pdf实现预览pdf&quot;">​</a></h1><blockquote><p>本节目标：理解“在移动端通过vue-pdf实现预览pdf”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 **应用场景：**比赛报表pdf文件需要在线预览跟下载，发现直接使用window.open(url, &#39;_blank&#39;)，在pc端是可以实现预览，但是在移动端是直接通过打开浏览器进行下载再预览，经查资料发现可以使用vue-pdf组件实现预览！！！ **参考：**<strong><a href="https://www.cnblogs.com/steamed-twisted-roll/p/9648255.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/steamed-twisted-roll/p/9648255.html</a></strong> GitHub地址:<a href="https://github.com/FranckFreiburger/vue-pdf#readme" target="_blank" rel="noreferrer">https://github.com/FranckFreiburger/vue-pdf#readme</a><strong>安装：</strong> npm install --save vue-pdf template代码:</p></blockquote><p>[](javascript:void(0)😉</p><p>&lt;template&gt;&lt;div class=&quot;pdf&quot; v-show=&quot;fileType === &#39;pdf&#39;&quot;&gt; &lt;p class=&quot;arrow&quot;&gt; &lt;!-- // 上一页 --&gt; &lt;span @click=&quot;changePdfPage(0)&quot; class=&quot;turn&quot; :class=&quot;{grey: currentPage==1}&quot;&gt;Preview&lt;/span&gt; {{currentPage}} / {{pageCount}} &lt;!-- // 下一页 --&gt; &lt;span @click=&quot;changePdfPage(1)&quot; class=&quot;turn&quot; :class=&quot;{grey: currentPage==pageCount}&quot;&gt;Next&lt;/span&gt; &lt;/p&gt; &lt;!-- // 自己引入就可以使用,这里我的需求是做了分页功能,如果不需要分页功能,只要src就可以了 --&gt; &lt;pdf :src=&quot;pdfSrc&quot; :page=&quot;currentPage&quot; @num-pages=&quot;pageCount=$event&quot; @page-loaded=&quot;currentPage=$event&quot; @loaded=&quot;loadPdfHandler&quot; &gt; &lt;/pdf&gt; &lt;/div&gt;&lt;/template&gt;</p><p>[](javascript:void(0)😉</p><p>js代码:&lt;script&gt; <em>//</em> <em>引入__PDF</em></p><p>[](javascript:void(0)😉</p><p>import pdf from &#39;vue-pdf&#39; export default { metaInfo: { title: &#39;This is the test&#39;, meta: [ { charset: &#39;utf-8&#39; }, { name: &#39;viewport&#39;, content: &#39;width=device-width,initial-scale=1,minimum-scale=1,maximum-scale=2,user-scalable=yes&#39; } ] }, components: {pdf}, // props: [&#39;pdfSrc&#39;], data () { return { currentPage: 0, // pdf文件页码 pageCount: 0, // pdf文件总页数 fileType: &#39;pdf&#39;, // 文件类型pdfSrc: this.$route.query.url // pdf文件地址 } },created() {// 有时PDF文件地址会出现跨域的情况,这里最好处理一下 this.pdfSrc = pdf.createLoadingTask(this.pdfSrc) }, methods: { // 改变PDF页码,val传过来区分上一页下一页的值,0上一页,1下一页 changePdfPage (val) { // console.log(val) if (val === 0 &amp;&amp; this.currentPage &gt; 1) { this.currentPage-- // console.log(this.currentPage) } if (val === 1 &amp;&amp; this.currentPage &lt; this.pageCount) { this.currentPage++ // console.log(this.currentPage) } }, // pdf加载时 loadPdfHandler (e) { this.currentPage = 1 // 加载的时候先加载第一页 } } }</p><p>[](javascript:void(0)😉</p><p><strong>上面是有实现分页功能的</strong><strong>下面是没有分页功能</strong><strong>template<strong><strong>代码</strong></strong>:</strong></p><p>[](javascript:void(0)😉</p><p>&lt;template&gt; &lt;div class=&quot;pdf-box&quot;&gt; &lt;pdf v-for=&quot;i in numPages&quot; :key=&quot;i&quot; :src=&quot;pdfSrc&quot; :page=&quot;i&quot;&gt; &lt;/pdf&gt; &lt;/div&gt;&lt;/template&gt;</p><p>[](javascript:void(0)😉</p><p><strong>js****代码</strong></p><p>[](javascript:void(0)😉</p><p>import pdf from &#39;vue-pdf&#39;export default { metaInfo: { meta: [ { name: &#39;viewport&#39;, content: &#39;width=device-width,initial-scale=1,minimum-scale=1,maximum-scale=2,user-scalable=yes&#39; } ] }, components: { pdf }, data () { return {pdfSrc: this.$utils.DecryptUrl(this.$route.query).url, // pdf文件地址 numPages: undefined, } }, mounted() { // 有时PDF文件地址会出现跨域的情况,这里最好处理一下this.pdfSrc = pdf.createLoadingTask(this.pdfSrc) this.pdfSrc.then(pdf =&gt; { this.numPages = pdf.numPages }) }}&lt;/script&gt;</p><p>[](javascript:void(0)😉</p><p><strong>css</strong>**：**</p><p>[](javascript:void(0)😉</p><p>&lt;style lang=&quot;scss&quot; scoped&gt; .pdf-box { -webkit-box-sizing: border-box; box-sizing: border-box; max-width: 1024px; width: 100%; margin: 0 auto; overflow-x: hidden; height: 100%; overflow-y: auto; -webkit-overflow-scrolling: touch; font-size: .28rem; span { width: 100%; } }&lt;/style&gt; **最后：**我们发现了pdf在手机预览的时候，不可以放大，后面发现是因为入口文件设置了禁止用户缩放放大，我们可以借助vue-meta进行单独为这个组件设置动态meta，具体看下vue-meta使用。 &gt; 来自 &lt;<a href="https://www.cnblogs.com/qdlhj/p/11237040.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/qdlhj/p/11237040.html</a>&gt;</p></div>',1)])])}const g=e(r,[["render",s]]);export{f as __pageData,g as default};
